from intervals import merge_intervals
import copy

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- helpers (reference logic, obviously correct) ----------

def _check_valid(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError("invalid")


def point_set(intervals):
    pts = set()
    for s, e in intervals:
        for x in range(s, e + 1):
            pts.add(x)
    return pts


def is_union_covered(needle_start, needle_end, haystack_sorted):
    """Check [needle_start, needle_end] subset of union(haystack) for integer points."""
    cur = needle_start
    for hs, he in sorted(haystack_sorted):
        if he < cur:
            continue
        if hs > cur:
            return False
        # hs <= cur <= he
        cur = he + 1
        if cur > needle_end:
            return True
    return cur > needle_end


def unions_equal_as_sets(a, b):
    # every interval of a covered by union of b and vice versa
    for s, e in a:
        if not is_union_covered(s, e, b):
            return False
    for s, e in b:
        if not is_union_covered(s, e, a):
            return False
    return True


def reference_merge(intervals):
    items = sorted(intervals)
    if not items:
        return []
    out = []
    cs, ce = items[0]
    for s, e in items[1:]:
        if s <= ce:  # overlap or touch (share a point)
            if e > ce:
                ce = e
        else:
            out.append((cs, ce))
            cs, ce = s, e
    out.append((cs, ce))
    return out


# ---------- spec examples ----------

def test_example_classic():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]

def test_example_touching():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

def test_example_adjacent():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]

def test_example_unsorted():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]

def test_example_empty():
    assert merge_intervals([]) == []

def test_example_invalid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---------- explicit boundary tests ----------

def test_touching_single_point_merges():
    assert merge_intervals([(1, 2), (3, 3)]) == [(1, 2), (3, 3)]
    # (1,2)={1,2}, (3,3)={3} share nothing -> separate (sanity)
    assert merge_intervals([(1, 2), (2, 2)]) == [(1, 2)]
    assert merge_intervals([(2, 2), (2, 2)]) == [(2, 2)]

def test_contained_absorbed():
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]
    assert merge_intervals([(2, 3), (1, 10)]) == [(1, 10)]

def test_transitive_chain_collapses():
    assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]
    assert merge_intervals([(1, 2), (3, 4), (2, 3)]) == [(1, 4)]

def test_duplicates_collapse():
    assert merge_intervals([(1, 3), (1, 3)]) == [(1, 3)]

def test_adjacent_chain_stays_separate():
    assert merge_intervals([(1, 2), (3, 4), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]

def test_negative_and_zero():
    assert merge_intervals([(-5, -3), (-3, 0)]) == [(-5, 0)]
    assert merge_intervals([(-5, -4), (-3, -2)]) == [(-5, -4), (-3, -2)]


# ---------- large-span branch (defect hunting) ----------

BIG = (1 << 25) + 5  # > 1<<25 span

def test_large_span_adjacent_stays_separate():
    # triggers the large-interval path; adjacent must NOT merge
    assert merge_intervals([(0, 40000000), (40000001, 40000002)]) == [(0, 40000000), (40000001, 40000002)]

def test_large_span_adjacent_minimal():
    s = 0
    e = s + (1 << 25) + 1
    assert merge_intervals([(s, e), (e + 1, e + 2)]) == [(s, e), (e + 1, e + 2)]

def test_large_span_touching_merges():
    assert merge_intervals([(0, 40000000), (40000000, 40000001)]) == [(0, 40000001)]

def test_large_span_touching_at_boundary():
    s = 10
    e = s + (1 << 25) + 10
    assert merge_intervals([(s, e), (e, e + 5)]) == [(s, e + 5)]

def test_large_span_contained_absorbed():
    assert merge_intervals([(0, 50000000), (10, 20)]) == [(0, 50000000)]

def test_large_span_transitive_with_gap():
    # chain merges first two, third is adjacent-gap away so stays separate
    assert merge_intervals([(0, 40000000), (40000000, 40000005), (40000006, 40000010)]) == [(0, 40000005), (40000006, 40000010)]

def test_large_span_unsorted_adjacent():
    assert merge_intervals([(40000001, 40000002), (0, 40000000)]) == [(0, 40000000), (40000001, 40000002)]

def test_large_span_negative_adjacent():
    assert merge_intervals([(-50000000, -10000000), (-9999999, 0)]) == [(-50000000, -10000000), (-9999999, 0)]


# ---------- property tests ----------

small_interval = st.tuples(st.integers(-10, 10), st.integers(-10, 10)).map(
    lambda t: (min(t[0], t[1]), max(t[0], t[1]))
)
small_lists = st.lists(small_interval, max_size=6)

@given(small_lists)
def test_property_sorted_by_start(intervals):
    out = merge_intervals(list(intervals))
    assert [s for s, _ in out] == sorted(s for s, _ in out)

@given(small_lists)
def test_property_disjoint_strict_gap(intervals):
    out = merge_intervals(list(intervals))
    for (ps, pe), (s, e) in zip(out, out[1:]):
        assert s > pe

@given(small_lists)
def test_property_coverage_equals_input_small(intervals):
    out = merge_intervals(list(intervals))
    assert point_set(out) == point_set(intervals)

@given(small_lists)
def test_property_matches_reference_model(intervals):
    assert merge_intervals(list(intervals)) == reference_merge(list(intervals))

@given(small_lists)
def test_property_idempotent(intervals):
    once = merge_intervals(list(intervals))
    assert merge_intervals(once) == once

@given(small_lists)
def test_property_input_not_mutated(intervals):
    orig = [(s, e) for s, e in intervals]
    snapshot = copy.deepcopy(orig)
    merge_intervals(orig)
    assert orig == snapshot

@given(small_lists)
def test_property_returns_new_list_of_tuples(intervals):
    inp = [(s, e) for s, e in intervals]
    out = merge_intervals(inp)
    assert out is not inp
    assert isinstance(out, list)
    for item in out:
        assert isinstance(item, tuple)
    # mutating output must not affect input
    if out:
        out.append((-999999, -999998))
        assert len(inp) == len(intervals)

@given(st.lists(st.tuples(st.integers(-20, 20), st.integers(-20, 20)), max_size=5))
def test_property_invalid_raises(intervals):
    assume(any(s > e for s, e in intervals))
    with pytest.raises(ValueError):
        merge_intervals(list(intervals))

@given(st.lists(st.tuples(st.integers(-5, 5), st.integers(-5, 5)).map(lambda t: (min(t[0], t[1]), max(t[0], t[1]))), max_size=4))
def test_property_single_point_valid(intervals):
    pts = [(x, x) for x in range(-3, 4)]
    out = merge_intervals(pts)
    assert out == [(-3, 4)]

@given(small_lists)
def test_property_output_intervals_valid(intervals):
    out = merge_intervals(list(intervals))
    for s, e in out:
        assert isinstance(s, int) and isinstance(e, int)
        assert s <= e

@given(st.integers(-50, 50), st.integers(0, 10), st.integers(-50, 50), st.integers(0, 10))
def test_property_touch_vs_adjacent_boundary(a, la, b, lb):
    # construct two intervals and check merge iff they share a point
    s1, e1 = a, a + la
    s2, e2 = b, b + lb
    out = merge_intervals([(s1, e1), (s2, e2)])
    share = not (e1 < s2 or e2 < s1)
    if share:
        # they must be in same output block (unless connected via nothing else -> single)
        assert len(out) == 1
        assert out[0] == (min(s1, s2), max(e1, e2))
    else:
        assert len(out) == 2

large_interval = st.tuples(st.integers(-10**9, 10**9), st.integers((1 << 25) + 1, (1 << 25) + 100)).map(
    lambda t: (t[0], t[0] + t[1])
)
large_lists = st.lists(
    st.one_of(
        large_interval,
        st.tuples(st.integers(-10**9, 10**9), st.integers(-10**9, 10**9)).map(
            lambda t: (min(t[0], t[1]), max(t[0], t[1]))
        ),
    ),
    max_size=4,
)

@given(large_lists)
def test_property_large_matches_reference(intervals):
    assert merge_intervals(list(intervals)) == reference_merge(list(intervals))

@given(large_lists)
def test_property_large_coverage(intervals):
    out = merge_intervals(list(intervals))
    assert unions_equal_as_sets(intervals, out)
    for (ps, pe), (s, e) in zip(out, out[1:]):
        assert s > pe
